// Presence is separate from a character record and from relationship tiers.
export function travelerStatus(s) {
  if (s.party?.traveler) return s.party.traveler
  // Read old saves without rewriting their journal. Explicit avoidance wins over
  // the companion record automatically generated by older releases.
  const active = s.mode === 'solo' && Boolean(s.characters.traveler) && !s.world.flags.no_traveler_premise
  return { met: active, joined: active, present: active }
}

export function ensureParticipation(s) {
  const status = travelerStatus(s)
  s.party ??= {}
  s.party.traveler ??= { ...status }
}

export function presentCharacters(s) {
  const traveler = travelerStatus(s)
  return Object.values(s.characters).filter(a => a.id !== 'traveler' || (traveler.met && traveler.joined && traveler.present))
}

export function sceneCharacters(s) {
  const members = s.scene?.members
  return presentCharacters(s).filter(a => !members || members.includes(a.id))
}

export function battleCharacters(s) {
  const ids = new Set(s.battle?.party.map(a => a.id) ?? [])
  return sceneCharacters(s).filter(a => ids.has(a.id))
}
